#!/usr/bin/env python3
"""
ClawShield Lite
A lightweight security analysis skill that scans AI skill code for risky
patterns and outputs a structured risk report.
"""

import sys
import json
import re
import os


def load_rules():
    rules_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "rules.json")
    with open(rules_path, "r") as f:
        return json.load(f)


def scan_code(code, rules):
    findings = {"dangerous": [], "suspicious": []}

    for category in ("dangerous", "suspicious"):
        for rule in rules.get(category, []):
            pattern = rule["pattern"]
            description = rule.get("description", "")
            for match in re.finditer(pattern, code):
                findings[category].append({
                    "pattern": pattern,
                    "description": description,
                    "match": match.group(0),
                    "position": match.start()
                })

    return findings


def determine_risk_level(findings):
    if findings["dangerous"]:
        return "HIGH RISK"
    if findings["suspicious"]:
        return "MEDIUM RISK"
    return "SAFE"


def main():
    code = sys.stdin.read()

    rules = load_rules()
    findings = scan_code(code, rules)
    risk_level = determine_risk_level(findings)

    report = {
        "risk_level": risk_level,
        "dangerous_findings": findings["dangerous"],
        "suspicious_findings": findings["suspicious"],
        "summary": {
            "dangerous_count": len(findings["dangerous"]),
            "suspicious_count": len(findings["suspicious"])
        }
    }

    print(json.dumps(report, indent=2))


if __name__ == "__main__":
    main()
EOF
